+var modelUsageFields = [][2]string{{"inputTokens", "input"}, {"cacheReadInputTokens", "cached"}, {"outputTokens", "output"}, {"costUSD", "cost_usd"}}
+
+// addModelRoundUsage adds model_round_usage: for each model of model_usage, what this round added
+// to the session's totals since the last successful round. With advance, the result's usable
+// values become each model's baseline.
+func (s *session) addModelRoundUsage(event, res map[string]any, advance bool) {
+	breakdown, ok := res["modelUsage"].(map[string]any)
+	if !ok {
+		return
+	}
+	var ids []string
+	for id, value := range breakdown {
+		if _, ok := value.(map[string]any); ok {
+			ids = append(ids, id)
+		}
+	}
+	sort.Strings(ids)
+	var entries []map[string]any
+	next := map[string]map[string]float64{}
+	for _, id := range ids[:min(len(ids), 20)] {
+		fields := breakdown[id].(map[string]any)
+		entry := map[string]any{"model": boundBytes(id, 256)}
+		base := map[string]float64{}
+		for _, pair := range modelUsageFields {
+			now, ok := number(fields[pair[0]])
+			if !ok {
+				continue
+			}
+			prev, seen := s.modelBase[id][pair[1]]
+			if !seen {
+				prev = 0
+			}
+			if now >= prev {
+				entry[pair[1]] = math.Round((now-prev)*1e9) / 1e9
+			}
+			base[pair[1]] = now
+		}
+		next[id] = base
+		if len(entry) > 1 {
+			entries = append(entries, entry)
+		}
+	}
+	if len(entries) > 0 {
+		event["model_round_usage"] = entries
+	}
+	if advance {
+		if s.modelBase == nil {
+			s.modelBase = map[string]map[string]float64{}
+		}
+		for id, base := range next {
+			if s.modelBase[id] == nil {
+				s.modelBase[id] = map[string]float64{}
+			}
+			for k, v := range base {
+				s.modelBase[id][k] = v
+			}
+		}
+	}
+}
